// Review dashboard (AEO-7 Monday review surface): reads data/geo.db, writes
// data/dashboard.html - a single self-contained file, no external assets.
// Regenerated by the daily scheduled task after run+extract.
//
// Reporting axes : headline numbers are NON-BRANDED (cat:company
// excluded); a category card breaks out use-case / feature / comparison /
// company; the ledger expands to the specific cited URLs; a Next actions
// section turns gaps into write/pitch/engage items.

import { Database } from "bun:sqlite";
import { join } from "node:path";
import { existsSync, readFileSync } from "node:fs";
import { BRAND_NAME, BRAND_DOMAIN, isOwnDomain } from "./brand.ts";

const DB_PATH = join(import.meta.dir, "..", "data", "geo.db");
const OUT_PATH = join(import.meta.dir, "..", "data", "dashboard.html");
const db = new Database(DB_PATH, { readonly: true });

const esc = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const pct = (n: number, d: number) => (d === 0 ? 0 : (100 * n) / d);
const fmtPct = (v: number) => `${v.toFixed(v >= 10 ? 0 : 1)}%`;
const host = (u: string) => {
  try { return new URL(u).hostname.replace(/^www\./, ""); } catch { return ""; }
};

const SURFACES = ["gpt", "claude", "perplexity", "gemini", "google-aio", "google-ai-mode"];
const SURFACE_LABEL: Record<string, string> = {
  gpt: "ChatGPT", claude: "Claude", perplexity: "Perplexity",
  gemini: "Gemini", "google-aio": "Google AIO", "google-ai-mode": "AI Mode"
};
const CATS = ["use-case", "feature", "comparison", "company"];
const CAT_LABEL: Record<string, string> = {
  "use-case": "Use case", feature: "Feature", comparison: "Comparison", company: "Company (branded)"
};

// --- questions + category map ------------------------------------------------

const questions = db.query("SELECT id, text, tags FROM questions WHERE active = 1 ORDER BY id")
  .all() as { id: number; text: string; tags: string }[];
const qCat = new Map<number, string>();
for (const q of questions) {
  const m = q.tags.match(/cat:([a-z-]+)/);
  qCat.set(q.id, m ? m[1] : "use-case");
}
const isBranded = (qid: number) => qCat.get(qid) === "company";

// --- runs (latest row per question x model x day) -----------------------------

interface DayRow {
  id: number; d: string; model: string; question_id: number; ok: number;
  mentioned: number; cited: number; citations: string;
}
const rows = db.query(`
  WITH latest AS (
    SELECT r.*, ROW_NUMBER() OVER (
      PARTITION BY r.question_id, r.model, date(r.run_ts) ORDER BY r.run_ts DESC
    ) rn FROM runs r
  )
  SELECT l.id, date(l.run_ts) d, l.model, l.question_id,
         -- An unrendered SERP is not a measurement: it could not have mentioned
         -- anything, so counting it as a miss understates the mention rate.
         (l.error IS NULL AND (l.serp_state IS NULL OR l.serp_state != 'shell')) ok,
         COALESCE(m.mentioned, 0) mentioned,
         (l.citations LIKE '%' || $brandDomain || '%') cited,
         COALESCE(l.citations, '[]') citations
  FROM latest l LEFT JOIN mentions m ON m.run_id = l.id AND m.brand = $brand
  WHERE l.rn = 1
`).all({ $brandDomain: BRAND_DOMAIN, $brand: BRAND_NAME.toLowerCase() }) as DayRow[];

const days = [...new Set(rows.map((r) => r.d))].sort();
const today = days[days.length - 1] ?? "";
const last7 = new Set(days.slice(-7));
const prev7 = new Set(days.slice(-14, -7));

function rates(sel: (r: DayRow) => boolean) {
  const s = rows.filter((r) => sel(r) && r.ok);
  return { n: s.length, mentioned: s.filter((r) => r.mentioned).length, cited: s.filter((r) => r.cited).length };
}
const nb = (r: DayRow) => !isBranded(r.question_id);
const w = rates((r) => last7.has(r.d) && nb(r));
const p = rates((r) => prev7.has(r.d) && nb(r));
const todayRows = rows.filter((r) => r.d === today);
const todayOk = todayRows.filter((r) => r.ok).length;

const trend = days.slice(-30).map((d) => {
  const s = rates((r) => r.d === d && nb(r));
  return { d, mentioned: pct(s.mentioned, s.n), cited: pct(s.cited, s.n) };
});

const byCat = CATS.map((cat) => {
  const cur = rates((r) => last7.has(r.d) && qCat.get(r.question_id) === cat);
  const prv = rates((r) => prev7.has(r.d) && qCat.get(r.question_id) === cat);
  const nQ = questions.filter((q) => qCat.get(q.id) === cat).length;
  return { cat, nQ, cur, prv };
});

const bySurface = SURFACES.map((model) => {
  const s = rates((r) => r.model === model && last7.has(r.d) && nb(r));
  const fails = rows.filter((r) => r.model === model && r.d === today && !r.ok).length;
  return { model, ...s, rate: pct(s.mentioned, s.n), failsToday: fails };
});

// --- app vs API divergence ----------------------------------------
// Every API surface measures what a developer's request returns. The consumer
// apps are what a buyer actually sees, and they can differ: separate search
// stack, different system prompts, personalization. The whole AEO vendor
// category asserts API-as-proxy without measuring it; this is the measurement.
//
// Fair comparison needs the same questions on both sides, so each pair is
// restricted to questions that have a usable row on the app AND the API side
// inside the window. The app surfaces run weekly on 15 questions, hence 4 weeks
// rather than the 7 days the rest of the dashboard uses.

const DIVERGENCE_WINDOW_DAYS = 28;
const DIVERGENCE_THRESHOLD_PTS = 10;
const APP_PAIRS = [
  { engine: "ChatGPT (default)", app: "chatgpt-app", api: "gpt" },
  { engine: "ChatGPT (search forced)", app: "chatgpt-app-search", api: "gpt" },
  { engine: "Claude", app: "claude-app", api: "claude" },
  { engine: "Perplexity", app: "perplexity-app", api: "perplexity" }
];

// Calendar days, not days-with-data: slicing the observed-day list would stretch
// the "4 weeks" backwards through every outage and quietly compare against older
// answers than the label claims.
const windowStart = (() => {
  const t = new Date(`${today || "1970-01-01"}T00:00:00Z`);
  t.setUTCDate(t.getUTCDate() - (DIVERGENCE_WINDOW_DAYS - 1));
  return t.toISOString().slice(0, 10);
})();

const domainsOf = (rs: DayRow[]) => {
  const out = new Set<string>();
  for (const r of rs) {
    try {
      for (const u of JSON.parse(r.citations || "[]") as string[]) {
        const h = host(u);
        if (h) out.add(h);
      }
    } catch {
      // malformed citations JSON - skip the row's domains, keep its mention data
    }
  }
  return out;
};
const jaccard = (a: Set<string>, b: Set<string>) => {
  if (a.size === 0 && b.size === 0) return null; // no citations either side: undefined, not 1
  const inter = [...a].filter((x) => b.has(x)).length;
  return inter / (a.size + b.size - inter);
};

// Newest row per question, used for the citation comparison below.
const latestPerQuestion = (rs: DayRow[]) => {
  const best = new Map<number, DayRow>();
  for (const r of rs) {
    const cur = best.get(r.question_id);
    if (!cur || r.d > cur.d) best.set(r.question_id, r);
  }
  return best;
};

const divergence = APP_PAIRS.map(({ engine, app, api }) => {
  const inWindow = (m: string) => rows.filter((r) => r.model === m && r.d >= windowStart && r.ok);
  const appRows = inWindow(app);
  const apiRows = inWindow(api);
  const shared = new Set(
    appRows.map((r) => r.question_id).filter((q) => apiRows.some((r) => r.question_id === q))
  );
  const a = appRows.filter((r) => shared.has(r.question_id));
  const b = apiRows.filter((r) => shared.has(r.question_id));

  // Mention rate pools every row: both sides are means, so the API's heavier
  // sampling makes its estimate steadier without biasing it either way.
  const appRate = pct(a.filter((r) => r.mentioned).length, a.length);
  const apiRate = pct(b.filter((r) => r.mentioned).length, b.length);

  // Jaccard cannot be pooled the same way. A union only grows with every extra
  // row, and the API runs daily against the app's weekly pass, so pooling would
  // report a widening gap that is an artifact of sampling more often on one
  // side. Compare like with like instead - newest app answer against newest API
  // answer, one question at a time - and average those.
  const aLatest = latestPerQuestion(a);
  const bLatest = latestPerQuestion(b);
  const perQuestion: number[] = [];
  for (const qid of shared) {
    const ra = aLatest.get(qid);
    const rb = bLatest.get(qid);
    if (!ra || !rb) continue;
    const j = jaccard(domainsOf([ra]), domainsOf([rb]));
    if (j !== null) perQuestion.push(j); // neither side cited anything: no signal
  }

  return {
    engine,
    questions: shared.size,
    appN: a.length,
    apiN: b.length,
    appRate,
    apiRate,
    delta: Math.abs(appRate - apiRate),
    overlap: perQuestion.length
      ? perQuestion.reduce((s, x) => s + x, 0) / perQuestion.length
      : null,
    overlapN: perQuestion.length,
    lastApp: appRows.map((r) => r.d).sort().at(-1) ?? null
  };
}).filter((d) => d.appN > 0);

// competitor appearances (7d, non-branded)
const compCounts = new Map<string, number>();
const compRows = db.query(`
  WITH latest AS (
    SELECT r.id, r.question_id, date(r.run_ts) d, ROW_NUMBER() OVER (
      PARTITION BY r.question_id, r.model, date(r.run_ts) ORDER BY r.run_ts DESC
    ) rn FROM runs r WHERE r.error IS NULL
  )
  SELECT m.competitors, l.d, l.question_id qid FROM mentions m
  JOIN latest l ON l.id = m.run_id AND l.rn = 1 WHERE m.brand = $brand
`).all({ $brand: BRAND_NAME.toLowerCase() }) as { competitors: string; d: string; qid: number }[];
for (const m of compRows) {
  if (!last7.has(m.d) || isBranded(m.qid)) continue;
  try { for (const c of JSON.parse(m.competitors ?? "[]")) compCounts.set(c, (compCounts.get(c) ?? 0) + 1); } catch {}
}
const competitors = [...compCounts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 10);

// --- URL-level citation ledger (non-branded, last 7 days) ----------------------

interface UrlStat { url: string; count: number; qids: Set<number> }
const urlByDomain = new Map<string, Map<string, UrlStat>>();
for (const r of rows) {
  if (!r.ok || !last7.has(r.d) || isBranded(r.question_id)) continue;
  let urls: string[] = [];
  try { urls = JSON.parse(r.citations); } catch { continue; }
  for (const u of urls) {
    const d = host(u);
    if (!d) continue;
    const clean = u.split("#")[0];
    const bucket = urlByDomain.get(d) ?? new Map<string, UrlStat>();
    const stat = bucket.get(clean) ?? { url: clean, count: 0, qids: new Set() };
    stat.count++; stat.qids.add(r.question_id);
    bucket.set(clean, stat); urlByDomain.set(d, bucket);
  }
}
const domainClass = new Map<string, string>(
  (db.query("SELECT domain, classification FROM domains").all() as any[]).map((d) => [d.domain, d.classification])
);
const ledger = [...urlByDomain.entries()]
  .map(([domain, urls]) => ({
    domain,
    classification: domainClass.get(domain) ?? "unclassified",
    total: [...urls.values()].reduce((a, b) => a + b.count, 0),
    urls: [...urls.values()].sort((a, b) => b.count - a.count).slice(0, 8)
  }))
  .sort((a, b) => b.total - a.total).slice(0, 25);
const domainTotal = (db.query("SELECT COUNT(*) c FROM domains").get() as any).c as number;

// --- next actions ---------------------------------------------------------------
// WRITE: non-branded questions with zero String presence this week, ranked by
// citations flowing to competitor/affiliate content. PITCH: cited publisher and
// affiliate domains. ENGAGE: most-cited community URLs.

const qWeek = new Map<number, { ok: number; present: number; domains: Map<string, { count: number; topUrl: string }> }>();
for (const r of rows) {
  if (!last7.has(r.d) || isBranded(r.question_id)) continue;
  const s = qWeek.get(r.question_id) ?? { ok: 0, present: 0, domains: new Map() };
  if (r.ok) s.ok++;
  if (r.mentioned || r.cited) s.present++;
  let urls: string[] = [];
  try { urls = JSON.parse(r.citations); } catch {}
  for (const u of urls) {
    const d = host(u);
    if (!d || isOwnDomain(d)) continue;
    const e = s.domains.get(d) ?? { count: 0, topUrl: u };
    e.count++; s.domains.set(d, e);
  }
  qWeek.set(r.question_id, s);
}
const contentClass = new Set(["competitor-owned", "affiliate-benchmark", "legit-publisher", "docs"]);
const writeTargets = [...qWeek.entries()]
  .filter(([qid, s]) => s.ok > 0 && s.present === 0)
  .map(([qid, s]) => {
    const winners = [...s.domains.entries()]
      .filter(([d]) => contentClass.has(domainClass.get(d) ?? ""))
      .sort((a, b) => b[1].count - a[1].count).slice(0, 2);
    const weight = winners.reduce((a, [, e]) => a + e.count, 0);
    return { qid, winners, weight };
  })
  .filter((t) => t.winners.length > 0)
  .sort((a, b) => b.weight - a.weight).slice(0, 6);

const pitchTargets = ledger
  .filter((l) => ["legit-publisher", "affiliate-benchmark"].includes(l.classification))
  .slice(0, 6);

const engageUrls = ledger
  .filter((l) => l.classification === "forum")
  .flatMap((l) => l.urls.map((u) => ({ ...u, domain: l.domain })))
  .sort((a, b) => b.count - a.count).slice(0, 6);

// --- svg helpers ----------------------------------------------------------------

const W = 640, H = 220, PAD = { t: 16, r: 96, b: 28, l: 40 };
function lineChart(): string {
  const data = trend;
  const iw = W - PAD.l - PAD.r, ih = H - PAD.t - PAD.b;
  const max = Math.max(10, ...data.map((t) => Math.max(t.mentioned, t.cited)));
  const x = (i: number) => PAD.l + (data.length === 1 ? iw / 2 : (i * iw) / (data.length - 1));
  const y = (v: number) => PAD.t + ih - (v / max) * ih;
  const path = (key: "mentioned" | "cited") =>
    data.map((t, i) => `${i === 0 ? "M" : "L"}${x(i).toFixed(1)},${y(t[key]).toFixed(1)}`).join(" ");
  const ticks = [0, max / 2, max];
  const grid = ticks.map((t) =>
    `<line x1="${PAD.l}" x2="${W - PAD.r}" y1="${y(t)}" y2="${y(t)}" class="grid"/>` +
    `<text x="${PAD.l - 6}" y="${y(t) + 3.5}" class="tick" text-anchor="end">${t.toFixed(0)}%</text>`
  ).join("");
  const xlabels = data.map((t, i) =>
    i === 0 || i === data.length - 1 || data.length <= 7
      ? `<text x="${x(i)}" y="${H - 8}" class="tick" text-anchor="middle">${t.d.slice(5)}</text>` : ""
  ).join("");
  const dots = (key: "mentioned" | "cited", cls: string) =>
    data.map((t, i) =>
      `<circle cx="${x(i)}" cy="${y(t[key])}" r="4" class="${cls}" data-tip="${t.d} — ${key}: ${fmtPct(t[key])}"/>`
    ).join("");
  const last = data[data.length - 1];
  // A fresh database has no runs yet; render a placeholder instead of crashing.
  if (!last) return `<p class="sub">No runs stored yet. Run <code>make run-core</code>, then regenerate.</p>`;
  return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Daily non-branded mention and citation rate">
    ${grid}
    <path d="${path("mentioned")}" class="l1"/><path d="${path("cited")}" class="l2"/>
    ${dots("mentioned", "d1")}${dots("cited", "d2")}
    <text x="${x(data.length - 1) + 10}" y="${y(last.mentioned) + 4}" class="dl c1">Mentioned</text>
    <text x="${x(data.length - 1) + 10}" y="${y(last.cited) + (Math.abs(y(last.cited) - y(last.mentioned)) < 14 ? 18 : 4)}" class="dl c2">Cited</text>
    ${xlabels}
  </svg>`;
}

function barChart(): string {
  const bw = 44, gap = 34, bl = 46;
  const w2 = bl + SURFACES.length * (bw + gap), h2 = 190, padT = 14, padB = 34;
  const ih = h2 - padT - padB;
  const max = Math.max(10, ...bySurface.map((s) => s.rate));
  const y = (v: number) => padT + ih - (v / max) * ih;
  const bars = bySurface.map((s, i) => {
    const bx = bl + i * (bw + gap);
    const by = y(s.rate), bh = Math.max(padT + ih - by, s.rate > 0 ? 4 : 0);
    return `
      <rect x="${bx}" y="${s.rate > 0 ? by : padT + ih - 1}" width="${bw}" height="${Math.max(bh, 1)}" rx="4" class="bar${s.n === 0 ? " nodata" : ""}"
        data-tip="${SURFACE_LABEL[s.model]}: ${s.n === 0 ? "no successful runs" : `${fmtPct(s.rate)} mentioned (${s.mentioned}/${s.n})`}"/>
      <text x="${bx + bw / 2}" y="${(s.rate > 0 ? by : padT + ih) - 6}" class="val" text-anchor="middle">${s.n === 0 ? "—" : fmtPct(s.rate)}</text>
      <text x="${bx + bw / 2}" y="${h2 - 16}" class="tick" text-anchor="middle">${SURFACE_LABEL[s.model]}</text>
      ${s.failsToday > 0 ? `<text x="${bx + bw / 2}" y="${h2 - 4}" class="fail" text-anchor="middle">${s.failsToday} failed</text>` : ""}`;
  }).join("");
  return `<svg viewBox="0 0 ${w2} ${h2}" role="img" aria-label="Non-branded mention rate by surface, last 7 days">
    <line x1="${bl - 6}" x2="${w2}" y1="${padT + ih}" y2="${padT + ih}" class="axis"/>${bars}
  </svg>`;
}

function compChart(): string {
  if (competitors.length === 0) return `<p class="empty">No competitor mentions extracted yet.</p>`;
  const rowH = 26, lw = 130, w3 = 560, h3 = competitors.length * rowH + 8;
  const max = Math.max(...competitors.map((c) => c[1]));
  const bars = competitors.map(([name, count], i) => {
    const bw = Math.max(4, ((w3 - lw - 60) * count) / max);
    const cy = 4 + i * rowH;
    return `
      <text x="${lw - 8}" y="${cy + 15}" class="tick" text-anchor="end">${esc(name)}</text>
      <rect x="${lw}" y="${cy + 4}" width="${bw}" height="14" rx="4" class="bar" data-tip="${esc(name)}: in ${count} non-branded answers (7d)"/>
      <text x="${lw + bw + 6}" y="${cy + 15}" class="val">${count}</text>`;
  }).join("");
  return `<svg viewBox="0 0 ${w3} ${h3}" role="img" aria-label="Competitor appearances, last 7 days">${bars}</svg>`;
}

// --- html blocks -----------------------------------------------------------------

const CLS_LABEL: Record<string, string> = {
  "legit-publisher": "publisher", "affiliate-benchmark": "affiliate", astroturf: "astroturf",
  "competitor-owned": "competitor", forum: "forum", docs: "docs", unclassified: "new"
};
const delta = (cur: number, prev: number, had: boolean) => {
  if (!had) return `<span class="sub">first week</span>`;
  const d = cur - prev;
  const cls = d > 0 ? "up" : d < 0 ? "down" : "sub";
  return `<span class="${cls}">${d > 0 ? "▲" : d < 0 ? "▼" : "•"} ${Math.abs(d).toFixed(1)}pt vs prior 7d</span>`;
};
const qText = new Map(questions.map((q) => [q.id, q.text]));

const catRows = byCat.map((c) => `
  <tr><td>${CAT_LABEL[c.cat]}</td><td class="num">${c.nQ}</td>
  <td class="num">${c.cur.n === 0 ? "—" : fmtPct(pct(c.cur.mentioned, c.cur.n))}</td>
  <td class="num">${c.cur.n === 0 ? "—" : fmtPct(pct(c.cur.cited, c.cur.n))}</td>
  <td>${c.cur.n === 0 ? "" : delta(pct(c.cur.mentioned, c.cur.n), pct(c.prv.mentioned, c.prv.n), c.prv.n > 0)}</td></tr>`).join("");

const gridSections = CATS.map((cat) => {
  const qs = questions.filter((q) => qCat.get(q.id) === cat);
  if (qs.length === 0) return "";
  const cellMap = new Map<string, DayRow>();
  for (const r of todayRows) cellMap.set(`${r.question_id}|${r.model}`, r);
  const body = qs.map((q) => {
    const cells = SURFACES.map((model) => {
      const r = cellMap.get(`${q.id}|${model}`);
      let cls = "none", label = "no run";
      if (r && !r.ok) { cls = "err"; label = "failed"; }
      else if (r && r.cited) { cls = "cited"; label = "cited"; }
      else if (r && r.mentioned) { cls = "ment"; label = "mentioned"; }
      else if (r) { cls = "abs"; label = "absent"; }
      return `<td><span class="pip ${cls}" data-tip="${esc(q.text.slice(0, 90))} — ${SURFACE_LABEL[model]}: ${label}"></span></td>`;
    }).join("");
    return `<tr><td class="qt">${esc(q.text)}</td>${cells}</tr>`;
  }).join("\n");
  return `<tr class="cathead"><td colspan="7">${CAT_LABEL[cat]}</td></tr>\n${body}`;
}).join("\n");

const ledgerRows = ledger.map((l) => {
  const urls = l.urls.map((u) =>
    `<li><a href="${esc(u.url)}" target="_blank" rel="noopener">${esc(u.url.replace(/^https?:\/\/(www\.)?/, "").slice(0, 90))}</a>
     <span class="sub">×${u.count} · ${[...u.qids].slice(0, 3).map((q) => `Q${q}`).join(", ")}</span></li>`
  ).join("");
  return `<tr><td>
    <details><summary>${esc(l.domain)}</summary><ul class="urls">${urls}</ul></details></td>
    <td><span class="chip ${CLS_LABEL[l.classification] ?? "new"}">${CLS_LABEL[l.classification] ?? l.classification}</span></td>
    <td class="num">${l.total}</td></tr>`;
}).join("\n");

const divergenceCard = divergence.length === 0
  ? `<p class="empty">No consumer-app runs yet. <code>make apps</code> runs the weekly pass over 15 tier-1 questions; the comparison appears once both sides have data on the same questions.</p>`
  : `<table><thead><tr><th>Engine</th><th class="num">Questions</th><th class="num">App rate</th>
      <th class="num">API rate</th><th class="num">Δ points</th><th class="num">Citation overlap</th><th>Last app run</th></tr></thead>
    <tbody>${divergence.map((d) => `
      <tr><td>${d.engine}</td><td class="num">${d.questions}</td>
      <td class="num">${d.appN === 0 ? "—" : fmtPct(d.appRate)}</td>
      <td class="num">${d.apiN === 0 ? "—" : fmtPct(d.apiRate)}</td>
      <td class="num"><strong>${d.questions === 0 ? "—" : d.delta.toFixed(0)}</strong></td>
      <td class="num">${d.overlap === null ? "—" : `${d.overlap.toFixed(2)}<span class="sub"> (${d.overlapN}q)</span>`}</td>
      <td>${d.lastApp ?? "—"}</td></tr>`).join("")}</tbody></table>
    <p class="sub" style="margin-top:8px">
      ${DIVERGENCE_WINDOW_DAYS}-day window, restricted to questions measured on both sides.
      Mention rates pool every run in the window. Citation overlap is the Jaccard index of cited-domain sets, compared newest-app-answer against newest-API-answer per question and averaged over the questions where at least one side cited something (count in brackets) - pooling a month of daily API runs against a weekly app pass would shrink the overlap through sampling alone.
      1.00 means the app and the API cited exactly the same domains, 0.00 means no domain in common.
      <br><strong>Decision rule:</strong> while Δ stays under ~${DIVERGENCE_THRESHOLD_PTS} points, the API surfaces are a valid proxy for what buyers see and we can say so with evidence.
      Above that, weight the app numbers and flag it in the Monday review.
      ${divergence.some((d) => d.questions > 0 && d.delta >= DIVERGENCE_THRESHOLD_PTS)
        ? `<br><strong>Currently above the threshold.</strong> Treat API-only numbers as an understatement of the gap until this settles.`
        : ""}
      <br><strong>Citations are not like-for-like, and that is the finding.</strong> The API surfaces are called with web search switched on, so they always cite. The apps decide for themselves and often answer from memory without searching, so an app row with zero citations usually means no search happened rather than that extraction failed. Low overlap then reads as "the buyer's answer was not grounded in the live web at all", which matters more than citing different sources. Judge those questions on mention rate.
      <br>Samples are small by design: the app pass is weekly on 15 questions because automating a logged-in ChatGPT or Claude session is against those providers' terms. Read Δ as a direction, not a precise figure, until several weeks have accumulated.
    </p>`;

// ---- Weekly build & outreach cards (folded into the dashboard, Aug 10 2026) ----
// Three cards, each from its own source, each skipped when its source is absent:
//   1. Content to build   — from data/content-coverage.json (make content-coverage)
//   2. Copy this          — competitor pages the engines cite on questions we lose
//   3. Question x surface  — the per-question grid for the latest day

const THEME_ORDER = ["brand", "compliance", "ai-data", "scale-pricing", "category", "blocking", "data-jobs"];
const THEME_LABEL: Record<string, string> = {
  brand: `Brand — questions about ${BRAND_NAME} itself`,
  compliance: "Compliance & legal",
  "ai-data": "AI agents, RAG & MCP",
  "scale-pricing": "Scale & pricing",
  category: "Comparisons & alternatives",
  blocking: "Anti-bot how-tos",
  "data-jobs": "Per-site scraping how-tos",
  other: "Other"
};
const THEME_DECISION: Record<string, string> = {
  brand: "build-first", compliance: "build", "ai-data": "build", "scale-pricing": "fix",
  category: "build", blocking: "mixed", "data-jobs": "defer", other: "review"
};
const themeOf = (t: string) => THEME_ORDER.find((k) => (t || "").includes(`theme:${k}`)) ?? "other";

const COVERAGE_PATH = join(import.meta.dir, "..", "data", "content-coverage.json");
type CovRow = { id: number; question: string; verdict: string; gap: string; tags: string };
const coverageRows: CovRow[] = existsSync(COVERAGE_PATH)
  ? (JSON.parse(readFileSync(COVERAGE_PATH, "utf8")).questions ?? [])
  : [];
const covSummary = {
  answered: coverageRows.filter((r) => r.verdict === "answered").length,
  partial: coverageRows.filter((r) => r.verdict === "partial").length,
  missing: coverageRows.filter((r) => r.verdict === "missing").length
};
const buildGroups = THEME_ORDER.map((theme) => ({
  theme,
  items: coverageRows.filter((r) => r.verdict === "missing" && themeOf(r.tags) === theme)
})).filter((g) => g.items.length > 0);

// Copy this: competitor / affiliate pages the engines cite on questions where
// our own domain is NOT cited. These are the pages to replicate as our own.
const clsMap = new Map<string, string>();
for (const row of db.query("SELECT domain, classification FROM domains").all() as { domain: string; classification: string }[]) {
  clsMap.set(row.domain, row.classification);
}
const copyRows = db
  .query(
    `SELECT r.question_id qid, q.text qtext, r.citations FROM runs r JOIN questions q ON q.id = r.question_id
     WHERE r.model IN ('gpt','claude','perplexity','gemini') AND date(r.run_ts) >= date('now','-30 days')
       AND r.citations IS NOT NULL AND r.citations != '[]'`
  )
  .all() as { qid: number; qtext: string; citations: string }[];
const qCitedHosts = new Map<number, Set<string>>();
const copyMap = new Map<string, { url: string; domain: string; cls: string; cites: number; qids: Set<number>; sampleQ: string }>();
for (const row of copyRows) {
  let urls: string[] = [];
  try { urls = JSON.parse(row.citations); } catch { continue; }
  const hs = qCitedHosts.get(row.qid) ?? new Set<string>();
  for (const u of urls) {
    const h = host(u);
    if (!h) continue;
    hs.add(h);
    const dom = h.split(".").slice(-2).join(".");
    const cls = clsMap.get(h) ?? clsMap.get(dom) ?? "";
    if (cls === "competitor-owned" || cls === "affiliate-benchmark") {
      const key = u.split("?")[0];
      const e = copyMap.get(key) ?? { url: key, domain: dom, cls, cites: 0, qids: new Set<number>(), sampleQ: row.qtext };
      e.cites++; e.qids.add(row.qid); copyMap.set(key, e);
    }
  }
  qCitedHosts.set(row.qid, hs);
}
const isLost = (qid: number) =>
  ![...(qCitedHosts.get(qid) ?? new Set())].some((h) => isOwnDomain(h as string));
const copyTargets = [...copyMap.values()]
  .map((e) => ({ ...e, lostQ: [...e.qids].filter(isLost) }))
  .filter((e) => e.lostQ.length > 0)
  .sort((a, b) => b.cites - a.cites || b.lostQ.length - a.lostQ.length)
  .slice(0, 15);


const DEC_LABEL: Record<string, string> = {
  "build-first": "build first", build: "build", fix: "fix", mixed: "mixed", defer: "defer", review: "review"
};
const BUCKET_LABEL: Record<string, string> = {
  contact: "contact", placement: "placement", counter: "competitor", review: "review"
};

const buildCard = buildGroups.length === 0
  ? `<p class="empty">No coverage grade yet. Run <code>make content-coverage</code>, then regenerate.</p>`
  : `<p class="sub" style="margin:0 0 12px">Coverage: <strong>${covSummary.answered}</strong> answered · <strong>${covSummary.partial}</strong> partial · <strong>${covSummary.missing}</strong> missing. Groups are in build priority.</p>` +
    buildGroups.map((g) => `<div class="bgrp b-${THEME_DECISION[g.theme]}">
      <div class="bgrp-h"><span class="chip b-${THEME_DECISION[g.theme]}">${DEC_LABEL[THEME_DECISION[g.theme]]}</span>
        <strong>${esc(THEME_LABEL[g.theme])}</strong><span class="sub">${g.items.length} missing</span></div>
      <ul class="blist">${g.items.map((i) => `<li>${esc(i.question)}${i.gap ? `<span class="sub"> — ${esc(i.gap)}</span>` : ""}</li>`).join("")}</ul>
    </div>`).join("");

const copyCard = copyTargets.length === 0
  ? `<p class="empty">No competitor pages cited on lost questions this window.</p>`
  : `<p class="sub" style="margin:0 0 10px">Pages the engines cite on questions we lose. Write our own version of each; the citation count is the demand behind it.</p>
    <ol class="copyl">${copyTargets.map((t) => `<li>
      <a href="${esc(t.url)}" target="_blank" rel="noopener">${esc(t.url.replace(/^https?:\/\/(www\.)?/, "").slice(0, 82))}</a>
      <span class="chip ${CLS_LABEL[t.cls] ?? "new"}">${esc(t.domain)}</span>
      <span class="sub">×${t.cites} citations · wins ${t.lostQ.length} question${t.lostQ.length === 1 ? "" : "s"} we lose · e.g. "${esc(t.sampleQ.slice(0, 60))}"</span></li>`).join("")}</ol>`;

const writeList = writeTargets.length === 0 ? `<p class="empty">No zero-presence questions with content-shaped winners this week.</p>` :
  `<ol>${writeTargets.map((t) => `<li><span class="qname">${esc(qText.get(t.qid) ?? "")}</span><br>
   <span class="sub">winning today: ${t.winners.map(([d, e]) => `<a href="${esc(e.topUrl)}" target="_blank" rel="noopener">${esc(d)}</a> (×${e.count})`).join(" · ")}</span></li>`).join("")}</ol>`;

const pitchList = pitchTargets.length === 0 ? `<p class="empty">No publisher/affiliate domains cited this week.</p>` :
  `<ol>${pitchTargets.map((l) => `<li><span class="qname">${esc(l.domain)}</span> <span class="chip ${CLS_LABEL[l.classification]}">${CLS_LABEL[l.classification]}</span>
   <span class="sub">top cited: <a href="${esc(l.urls[0]?.url ?? "#")}" target="_blank" rel="noopener">${esc((l.urls[0]?.url ?? "").replace(/^https?:\/\/(www\.)?/, "").slice(0, 80))}</a> ×${l.urls[0]?.count ?? 0}</span></li>`).join("")}</ol>`;

const engageList = engageUrls.length === 0 ? `<p class="empty">No community URLs cited this week.</p>` :
  `<ol>${engageUrls.map((u) => `<li><a href="${esc(u.url)}" target="_blank" rel="noopener">${esc(u.url.replace(/^https?:\/\/(www\.)?/, "").slice(0, 90))}</a>
   <span class="sub">×${u.count} · ${u.domain}</span></li>`).join("")}</ol>`;


// ---- Measurement-pack cards (rank / routing / objections / sentiment / robots) ----
// Each reads its own JSON side-output and degrades to "not yet computed" when
// the file is missing - the pack runs on its own cadence (make weekly-measure).

const readJson = (name: string): any | null => {
  const p = join(import.meta.dir, "..", "data", name);
  if (!existsSync(p)) return null;
  try { return JSON.parse(readFileSync(p, "utf8")); } catch { return null; }
};
const notComputed = (target: string) =>
  `<p class="empty">Not yet computed. Run <code>make ${target}</code>, then regenerate.</p>`;

const rankData = readJson("visibility-rank.json");
const rankCard = !rankData
  ? notComputed("rank")
  : (() => {
      const s = rankData.overall.brand;
      const move = (m: number | null) =>
        m === null ? `<span class="sub">new</span>` :
        m === 0 ? `<span class="sub">•</span>` :
        m > 0 ? `<span class="up">▲ +${m}</span>` : `<span class="down">▼ ${m}</span>`;
      const ladder = rankData.overall.top.map((b: any) => `<tr>
        <td class="num">${b.rank}</td><td>${esc(b.brand)}${b.brand === BRAND_NAME ? " <strong>← us</strong>" : ""}</td>
        <td class="num">${b.share.toFixed(1)}%</td><td class="num sub">${b.prevShare.toFixed(1)}%</td></tr>`).join("");
      const themeRows = (rankData.byTheme ?? []).map((t: any) => `<tr>
        <td>${esc(t.theme)}</td><td class="num">${t.brand.rank ?? "—"}</td>
        <td class="num">${t.brand.share.toFixed(1)}%</td><td>${move(t.brand.move)}</td>
        <td class="num sub">${t.rows}</td></tr>`).join("");
      const prioRows = (rankData.byPrio ?? []).map((p: any) => `<tr>
        <td>prio:${p.prio}</td><td class="num">${p.brand.rank ?? "—"}</td>
        <td class="num">${p.brand.share.toFixed(1)}%</td><td>${move(p.brand.move)}</td>
        <td class="num sub">${p.rows}</td></tr>`).join("");
      return `<p class="sub" style="margin:0 0 10px">${esc(BRAND_NAME)} is <strong>#${s.rank ?? "unranked"}</strong> at ${s.share}% share of voice
        (prev #${s.prevRank ?? "—"} at ${s.prevShare}%, ${move(s.move)}) over ${rankData.overall.rows} non-branded answers, trailing 7 days vs the 7 before.</p>
      <div class="row">
        <div><h3>Top brands — share of answers</h3>
        <table><thead><tr><th class="num">#</th><th>Brand</th><th class="num">Share</th><th class="num">Prev</th></tr></thead><tbody>${ladder}</tbody></table></div>
        <div><h3>${esc(BRAND_NAME)} per theme${prioRows ? " and prio" : ""}</h3>
        <table><thead><tr><th>Slice</th><th class="num">Rank</th><th class="num">Share</th><th>WoW</th><th class="num">n</th></tr></thead>
        <tbody>${themeRows}${prioRows}</tbody></table></div>
      </div>`;
    })();

const routingData = readJson("routing.json");
const routingCard = !routingData
  ? notComputed("routing")
  : `<table><thead><tr><th>Theme</th><th class="num">Validation</th><th class="num">Discovery</th><th>Verdict</th></tr></thead>
    <tbody>${(routingData.themes ?? []).map((t: any) => {
      const chip = t.verdict === "goal-state" ? "publisher" :
        t.verdict.startsWith("trust-gap") ? "affiliate" :
        t.verdict.startsWith("comprehension-gap") ? "competitor" : "new";
      return `<tr><td>${esc(t.theme)}</td>
        <td class="num">${t.validation ? `${t.validation.pct}% <span class="sub">(${t.validation.n})</span>` : "—"}</td>
        <td class="num">${t.discovery.pct}% <span class="sub">(${t.discovery.n})</span></td>
        <td><span class="chip ${chip}">${esc(t.verdict)}</span></td></tr>`;
    }).join("")}</tbody></table>
    <p class="sub" style="margin-top:8px">Validation = mention rate when a theme's fact is asked about directly (type:validation questions);
    discovery = mention rate on the theme's ordinary non-branded questions. Discovery ≥ ${routingData.thresholds?.discoveryGoalPct ?? 10}% is the goal state;
    below it, validation ≥ ${routingData.thresholds?.validationTrustPct ?? 60}% routes the work off-page, lower routes it on-page.</p>`;

const objectionsData = readJson("objections.json");
const objectionsCard = !objectionsData
  ? notComputed("objections")
  : (objectionsData.objections ?? []).length === 0
    ? `<p class="empty">No recurring objections: ${objectionsData.negativeRows} negative/inaccurate answers in the last ${objectionsData.windowDays} days.</p>`
    : `<table><thead><tr><th>Objection</th><th class="num">Count</th><th>In their words</th><th>Suggested reframe</th></tr></thead>
      <tbody>${objectionsData.objections.map((o: any) => `<tr>
        <td><strong>${esc(o.name)}</strong><br><span class="sub">${(o.source_questions ?? []).slice(0, 4).map((q: number) => `Q${q}`).join(", ")}</span></td>
        <td class="num">${o.count}</td>
        <td class="sub">“${esc(o.example_quote)}”</td>
        <td>${esc(o.suggested_reframe)}</td></tr>`).join("")}</tbody></table>
      <p class="sub" style="margin-top:8px">Clustered from ${objectionsData.negativeRows} negative/inaccurate answers (${objectionsData.windowDays}d), with ${objectionsData.neutralSample} neutral branded answers as contrast. Quotes are verbatim.</p>`;

const sentimentData = readJson("sentiment-by-attribute.json");
const sentimentCard = !sentimentData
  ? notComputed("sentiment")
  : (sentimentData.byTheme ?? []).length === 0
    ? `<p class="empty">No in-scope mention rows in the window (branded + type:sentiment questions).</p>`
    : `<p class="sub" style="margin:0 0 10px">${esc(sentimentData.scope ?? "")}. Net-positive = (positive − negative − inaccurate) / total.</p>
      <table><thead><tr><th>Attribute (theme)</th><th class="num">Pos</th><th class="num">Neu</th><th class="num">Neg</th><th class="num">Inacc</th><th class="num">Net-positive</th><th>WoW</th></tr></thead>
      <tbody>${sentimentData.byTheme.map((t: any) => `<tr>
        <td>${esc(t.theme)}</td>
        <td class="num">${t.counts.positive}</td><td class="num">${t.counts.neutral}</td>
        <td class="num">${t.counts.negative}</td><td class="num">${t.counts.inaccurate}</td>
        <td class="num">${t.netPositive === null ? "—" : `${t.netPositive}%`}</td>
        <td>${t.deltaPts === null ? `<span class="sub">first week</span>` :
          t.deltaPts > 0 ? `<span class="up">▲ ${t.deltaPts}pt</span>` :
          t.deltaPts < 0 ? `<span class="down">▼ ${Math.abs(t.deltaPts)}pt</span>` : `<span class="sub">flat</span>`}</td></tr>`).join("")}</tbody></table>`;

const robotsData = readJson("robots-audit.json");
const robotsCard = !robotsData
  ? notComputed("robots-audit")
  : (() => {
      const faults: string[] = robotsData.faults ?? [];
      const faultBlock = faults.length === 0
        ? `<p class="sub" style="margin:0 0 8px"><span class="up">No faults.</span> Every answer-retrieval and search-index crawler can reach the audited paths.</p>`
        : `<p style="margin:0 0 8px;color:var(--crit)"><strong>${faults.length} FAULT${faults.length === 1 ? "" : "S"}:</strong><br>${faults.map(esc).join("<br>")}</p>`;
      const hostTables = (robotsData.hosts ?? []).map((h: any) => `<div>
        <h3>${esc(h.host)} ${h.fetched ? "" : `<span class="down">robots.txt unreachable</span>`}</h3>
        ${(h.contentSignals ?? []).length ? `<p class="sub">${esc(h.contentSignals.join(" | "))}</p>` : ""}
        <table><thead><tr><th>Crawler</th><th>Role</th><th>Path</th><th>Governing group</th></tr></thead>
        <tbody>${(h.crawlers ?? []).map((c: any) => `<tr>
          <td>${esc(c.crawler)}</td><td class="sub">${esc(c.role)}</td>
          <td>${c.rootAllowed ? `<span class="up">allowed</span>` : c.fault ? `<span class="down">BLOCKED</span>` : `<span class="sub">blocked (policy)</span>`}</td>
          <td class="sub">[${esc(c.group)}]</td></tr>`).join("")}</tbody></table></div>`).join("");
      return `${faultBlock}
        <p class="sub" style="margin:0 0 10px">llms.txt: ${robotsData.llmsTxt?.ok ? `<span class="up">reachable (200)</span>` : `<span class="down">NOT OK (${robotsData.llmsTxt?.status ?? "unreachable"})</span>`}</p>
        <div class="row">${hostTables}</div>
        <p class="sub" style="margin-top:8px">A blocked answer-retrieval or search-index crawler is a fault (it zeroes a surface's ability to cite us). A blocked training crawler is a policy choice, noted only.</p>`;
    })();

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>GEO tracker — ${BRAND_NAME}</title>
<style>
:root {
  color-scheme: light;
  --page:#f9f9f7; --surface:#fcfcfb; --ink:#0b0b0b; --ink2:#52514e; --muted:#898781;
  --grid:#e1e0d9; --axis:#c3c2b7; --border:rgba(11,11,11,.10);
  --s1:#2a78d6; --s2:#eb6834; --s3:#1baf7a; --s4:#eda100; --s5:#e87ba4; --s6:#008300;
  --good:#006300; --crit:#d03b3b;
}
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
  color-scheme: dark;
  --page:#0d0d0d; --surface:#1a1a19; --ink:#ffffff; --ink2:#c3c2b7; --muted:#898781;
  --grid:#2c2c2a; --axis:#383835; --border:rgba(255,255,255,.10);
  --s1:#3987e5; --s2:#d95926; --s3:#199e70; --s4:#c98500; --s5:#d55181; --s6:#008300;
  --good:#0ca30c; --crit:#d03b3b;
}}
:root[data-theme="dark"] {
  color-scheme: dark;
  --page:#0d0d0d; --surface:#1a1a19; --ink:#ffffff; --ink2:#c3c2b7; --muted:#898781;
  --grid:#2c2c2a; --axis:#383835; --border:rgba(255,255,255,.10);
  --s1:#3987e5; --s2:#d95926; --s3:#199e70; --s4:#c98500; --s5:#d55181; --s6:#008300;
  --good:#0ca30c; --crit:#d03b3b;
}
* { box-sizing:border-box; margin:0 }
body { background:var(--page); color:var(--ink); font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif; padding:28px clamp(16px,4vw,48px) 64px; }
h1 { font-size:19px; font-weight:650 }
h2 { font-size:13px; font-weight:600; color:var(--ink2); text-transform:uppercase; letter-spacing:.04em; margin-bottom:10px }
h3 { font-size:12.5px; font-weight:600; color:var(--ink2); margin:14px 0 6px }
.meta { color:var(--muted); font-size:12.5px; margin-top:2px }
.tiles { display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:12px; margin:22px 0 }
.tile { background:var(--surface); border:1px solid var(--border); border-radius:10px; padding:14px 16px }
.tile .k { font-size:12px; color:var(--ink2) }
.tile .v { font-size:30px; font-weight:650; margin:2px 0 }
.tile .sub, .sub { font-size:12px; color:var(--muted) }
.up { font-size:12px; color:var(--good) } .down { font-size:12px; color:var(--crit) }
.card { background:var(--surface); border:1px solid var(--border); border-radius:10px; padding:16px 18px; margin-bottom:16px; overflow-x:auto }
.row { display:grid; grid-template-columns:1fr 1fr; gap:16px } @media (max-width:980px){ .row{grid-template-columns:1fr} }
.row3 { display:grid; grid-template-columns:1fr 1fr 1fr; gap:16px } @media (max-width:1100px){ .row3{grid-template-columns:1fr} }
svg { width:100%; height:auto; display:block }
.grid { stroke:var(--grid); stroke-width:1 } .axis { stroke:var(--axis); stroke-width:1 }
.tick { fill:var(--muted); font-size:11px; font-variant-numeric:tabular-nums }
.val { fill:var(--ink2); font-size:11px; font-variant-numeric:tabular-nums }
.fail { fill:var(--crit); font-size:10px }
.l1 { fill:none; stroke:var(--s1); stroke-width:2 } .l2 { fill:none; stroke:var(--s2); stroke-width:2 }
.d1 { fill:var(--s1); stroke:var(--surface); stroke-width:2 } .d2 { fill:var(--s2); stroke:var(--surface); stroke-width:2 }
.dl { font-size:11.5px; font-weight:600 } .c1 { fill:var(--s1) } .c2 { fill:var(--s2) }
.bar { fill:var(--s1) } .bar.nodata { fill:var(--grid) }
table { border-collapse:collapse; width:100%; font-size:13px }
th { text-align:left; color:var(--ink2); font-weight:600; font-size:12px; padding:6px 10px; border-bottom:1px solid var(--axis) }
td { padding:5px 10px; border-bottom:1px solid var(--grid); vertical-align:top }
td.num, th.num { text-align:right; font-variant-numeric:tabular-nums }
td.qt { max-width:420px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:var(--ink2) }
.cathead td { font-size:11.5px; font-weight:650; color:var(--ink2); text-transform:uppercase; letter-spacing:.04em; background:color-mix(in srgb, var(--grid) 40%, var(--surface)); padding:6px 10px }
.gridt th:not(:first-child), .gridt td:not(:first-child) { text-align:center }
.pip { display:inline-block; width:14px; height:14px; border-radius:4px; background:var(--grid) }
.pip.cited { background:var(--s1) } .pip.ment { border:2px solid var(--s1); background:transparent }
.pip.abs { background:var(--grid) } .pip.err { background:transparent; border:2px solid var(--crit) }
.pip.none { background:transparent; border:1px dashed var(--axis) }
.legend { display:flex; gap:18px; flex-wrap:wrap; font-size:12px; color:var(--ink2); margin:8px 2px 0 }
.legend .pip { vertical-align:-2px; margin-right:5px }
.chip { display:inline-block; font-size:11.5px; font-weight:600; padding:1.5px 8px; border-radius:99px; color:var(--ink); background:var(--grid) }
.chip.publisher { background:color-mix(in srgb,var(--s3) 22%,var(--surface)) }
.chip.affiliate { background:color-mix(in srgb,var(--s4) 26%,var(--surface)) }
.chip.competitor { background:color-mix(in srgb,var(--s2) 22%,var(--surface)) }
.chip.astroturf { background:color-mix(in srgb,var(--crit) 24%,var(--surface)) }
.chip.forum { background:color-mix(in srgb,var(--s5) 24%,var(--surface)) }
.chip.docs { background:color-mix(in srgb,var(--s1) 20%,var(--surface)) }
.empty { color:var(--muted); font-size:13px }
details summary { cursor:pointer; color:var(--ink); }
details summary:hover { color:var(--s1) }
ul.urls { margin:6px 0 4px 18px; padding:0 }
ul.urls li { margin:3px 0; font-size:12.5px }
a { color:var(--s1); text-decoration:none } a:hover { text-decoration:underline }
ol { margin:4px 0 0 18px; padding:0 } ol li { margin:8px 0; font-size:13px }
.qname { font-weight:600 }
#tip { position:fixed; pointer-events:none; background:var(--ink); color:var(--page); font-size:12px; padding:5px 9px; border-radius:6px; opacity:0; transition:opacity .08s; max-width:340px; z-index:9 }
/* weekly build cards */
ol.copyl li { margin:9px 0 }
ol.copyl .chip { margin:0 6px }
.bgrp { border-left:3px solid var(--axis); padding:2px 0 2px 12px; margin:10px 0 }
.bgrp.b-build-first { border-left-color:#0e9e52 } .bgrp.b-build { border-left-color:#0e9e52 }
.bgrp.b-fix { border-left-color:#b8770e } .bgrp.b-mixed { border-left-color:#b8770e }
.bgrp.b-defer { border-left-color:var(--muted) } .bgrp.b-review { border-left-color:var(--muted) }
.bgrp-h { display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:4px; font-size:13.5px }
.bgrp-h .sub { margin-left:auto }
ul.blist { margin:4px 0 0 16px; padding:0 } ul.blist li { margin:4px 0; font-size:12.5px }
.chip.b-build-first, .chip.b-build { background:#e1f4ea; color:#0e7d43 }
.chip.b-fix, .chip.b-mixed { background:#fbefd8; color:#8a5a08 }
.chip.b-defer, .chip.b-review { background:#eceae4; color:#6a6862 }
</style></head><body>
<h1>GEO tracker — ${BRAND_NAME}</h1>
<p class="meta">Generated ${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC · ${days.length} day${days.length === 1 ? "" : "s"} of data · latest run ${today} · headline numbers exclude branded questions</p>

<div class="tiles">
  <div class="tile"><div class="k">Cited (non-branded), last 7d</div><div class="v">${fmtPct(pct(w.cited, w.n))}</div>${delta(pct(w.cited, w.n), pct(p.cited, p.n), p.n > 0)}</div>
  <div class="tile"><div class="k">Mentioned (non-branded), last 7d</div><div class="v">${fmtPct(pct(w.mentioned, w.n))}</div>${delta(pct(w.mentioned, w.n), pct(p.mentioned, p.n), p.n > 0)}</div>
  <div class="tile"><div class="k">Coverage today</div><div class="v">${todayOk}<span style="font-size:16px;color:var(--muted)">/${todayRows.length}</span></div><span class="sub">successful runs / attempted</span></div>
  <div class="tile"><div class="k">Citation ledger</div><div class="v">${domainTotal}</div><span class="sub">domains seen · top ${ledger.length} below</span></div>
</div>

<div class="row">
  <div class="card"><h2>Non-branded mention & citation rate by day</h2>${lineChart()}</div>
  <div class="card"><h2>By question category — last 7 days</h2>
  <table><thead><tr><th>Category</th><th class="num">Questions</th><th class="num">Mentioned</th><th class="num">Cited</th><th></th></tr></thead>
  <tbody>${catRows}</tbody></table>
  <p class="sub" style="margin-top:8px">Company (branded) is tracked but excluded from every headline number and chart on this page.</p></div>
</div>

<div class="row">
  <div class="card"><h2>Mention rate by surface — non-branded, last 7 days</h2>${barChart()}</div>
  <div class="card"><h2>Competitors in answers — non-branded, last 7 days</h2>${compChart()}</div>
</div>

<div class="card"><h2>App vs API — what buyers see against what the API returns</h2>${divergenceCard}</div>

<div class="card"><h2>Visibility rank — ${esc(BRAND_NAME)} vs every competitor, 7d vs prior 7d</h2>${rankCard}</div>

<div class="card"><h2>Routing — validation × discovery, per theme (14d)</h2>${routingCard}</div>

<div class="card"><h2>Objections — what the engines hold against ${esc(BRAND_NAME)} (14d)</h2>${objectionsCard}</div>

<div class="card"><h2>Sentiment by attribute — branded &amp; sentiment questions (14d)</h2>${sentimentCard}</div>

<div class="card"><h2>Robots audit — can the AI crawlers get in?</h2>${robotsCard}</div>

<div class="card"><h2>Next actions — generated from this week's gaps</h2>
<div class="row3">
  <div><h3>✍️ Write — questions we lose to content pages</h3>${writeList}</div>
  <div><h3>📮 Pitch — cited publishers & benchmarks</h3>${pitchList}</div>
  <div><h3>💬 Engage — community threads LLMs cite</h3>${engageList}</div>
</div>
<p class="sub" style="margin-top:10px">Rule-generated shortlist from the citation ledger. Nothing here sends or publishes anything.</p></div>

<div class="card"><h2>Copy this — competitor content winning the questions we lose</h2>${copyCard}</div>

<div class="card"><h2>Content to build — where our own site is silent</h2>${buildCard}</div>

<div class="card"><h2>Question × surface — latest day, grouped by category</h2>
<table class="gridt"><thead><tr><th>Question</th>${SURFACES.map((s) => `<th>${SURFACE_LABEL[s]}</th>`).join("")}</tr></thead>
<tbody>${gridSections}</tbody></table>
<div class="legend">
  <span><span class="pip cited"></span>cited</span>
  <span><span class="pip ment"></span>mentioned, not cited</span>
  <span><span class="pip abs"></span>absent</span>
  <span><span class="pip err"></span>run failed</span>
  <span><span class="pip none"></span>no run yet</span>
</div></div>

<div class="card"><h2>Citation ledger — who LLMs cite on non-branded questions (7d)</h2>
<p class="sub" style="margin-bottom:8px">Click a domain to see the exact URLs being cited, with counts and the questions they won.</p>
<table><thead><tr><th>Domain (click to expand URLs)</th><th>Type</th><th class="num">Citations</th></tr></thead>
<tbody>${ledgerRows}</tbody></table></div>

<div id="tip"></div>
<script>
const tip = document.getElementById("tip");
document.addEventListener("mouseover", (e) => {
  const t = e.target.closest("[data-tip]");
  if (!t) { tip.style.opacity = 0; return; }
  tip.textContent = t.getAttribute("data-tip");
  tip.style.opacity = 1;
});
document.addEventListener("mousemove", (e) => {
  tip.style.left = Math.min(e.clientX + 14, innerWidth - tip.offsetWidth - 8) + "px";
  tip.style.top = (e.clientY + 16) + "px";
});
</script>
</body></html>`;

await Bun.write(OUT_PATH, html);
console.log(`dashboard: ${OUT_PATH} (${days.length} days, ${rows.length} run-rows, ${questions.length} questions)`);

// Side-output: everything the weekly PDF report needs, so `make report-pdf`
// never re-derives a metric. Written next to the HTML; report-pdf.ts reads it.
const REPORT_JSON = join(import.meta.dir, "..", "data", "weekly-report.json");
await Bun.write(
  REPORT_JSON,
  JSON.stringify(
    {
      generatedAt: new Date().toISOString(),
      today,
      days: days.length,
      bank: questions.length,
      headline: {
        cited: pct(w.cited, w.n), citedPrev: pct(p.cited, p.n),
        mentioned: pct(w.mentioned, w.n), mentionedPrev: pct(p.mentioned, p.n),
        n: w.n, priorN: p.n
      },
      coverage: covSummary,
      bySurface: bySurface.map((s) => ({
        surface: SURFACE_LABEL[s.model] ?? s.model,
        mentioned: pct(s.mentioned, s.n), cited: pct(s.cited, s.n), n: s.n
      })),
      byCat: byCat.map((c) => ({
        cat: CAT_LABEL[c.cat] ?? c.cat, nQ: c.nQ,
        mentioned: pct(c.cur.mentioned, c.cur.n), cited: pct(c.cur.cited, c.cur.n),
        mentionedPrev: pct(c.prv.mentioned, c.prv.n), n: c.cur.n
      })),
      competitors: competitors.map(([name, count]) => ({ name, count })),
      copyTargets: copyTargets.map((t) => ({
        url: t.url, domain: t.domain, cls: t.cls, cites: t.cites,
        lostQ: t.lostQ.length, sampleQ: t.sampleQ
      })),
      buildGroups: buildGroups.map((g) => ({
        theme: g.theme, label: THEME_LABEL[g.theme], decision: THEME_DECISION[g.theme],
        items: g.items.map((i) => ({ q: i.question, gap: i.gap }))
      })),
      pitch: pitchTargets.map((l) => ({
        domain: l.domain, classification: l.classification,
        topUrl: l.urls[0]?.url ?? ""
      }))
    },
    null,
    1
  )
);
console.log(`report data: ${REPORT_JSON}`);
